def rot(text, n):
    """Return text with each ASCII letter moved n places, wrapping and keeping case.

    n must be an int; floats, strings and bools raise ValueError. Other characters are unchanged.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"expected an integer shift, got {n!r}")
    shift = n % 26
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - ord("a") + shift) % 26 + ord("a")))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - ord("A") + shift) % 26 + ord("A")))
        else:
            out.append(ch)
    return "".join(out)

